// ─── File: StatsDemo.java ───
// Runnable demo: shows COUNT(*) vs COUNT(col) vs COUNT(DISTINCT) and AVG-with-NULL.
package com.bank.stats;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import java.util.logging.*;

public class StatsDemo {
    private static final Logger log = Logger.getLogger(StatsDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        AccountStatsService service = new AccountStatsService(repo);

        log.info(() -> "COUNT(*)                 = " + service.countAllRows());
        log.info(() -> "COUNT(phone)             = " + service.countPhones());
        log.info(() -> "COUNT(DISTINCT branch)   = " + service.countDistinctBranches());
        log.info(() -> "AVG(last_fee) (NULL skip)= " + service.averageFee());
        log.info(() -> "SUM(last_fee)            = Rs." + service.sumFee());
    }
}

// ─── Would be in model/Account.java ───
class Account {
    final String accountId, holderName, branch, phone; // phone may be null
    final BigDecimal lastFee;                           // may be null
    Account(String id, String name, String branch, String phone, BigDecimal fee) {
        this.accountId = id; this.holderName = name;
            this.branch = branch;
            this.phone = phone
            this.lastFee = fee;
    }
}

// ─── Would be in repository/AccountRepository.java ───
class AccountRepository {
    List<Account> findAll() {
        return List.of(
            new Account("SAV2001", "Rajesh Kumar", "Delhi",  "9876543210", new BigDecimal("50")),
            new Account("CUR3001", "Priya Sharma", "Mumbai", null,          null),
            new Account("SAV2002", "Amit Verma",   "Delhi",  "9811111111", new BigDecimal("75")),
            new Account("SAV2003", "Neha Gupta",   "Delhi",  null,          new BigDecimal("50")));
    }
}

// ─── Would be in service/AccountStatsService.java ───
class AccountStatsService {
    private final AccountRepository repo;
    AccountStatsService(AccountRepository repo) { this.repo = repo; }

    // COUNT(*): every row regardless of NULLs
    long countAllRows() { return repo.findAll().size(); }

    // COUNT(phone): only rows where phone IS NOT NULL
    long countPhones() {
        return repo.findAll().stream().filter(a -> a.phone != null).count();
    }

    // COUNT(DISTINCT branch): distinct non-null branch values
    long countDistinctBranches() {
        return repo.findAll().stream()
            .map(a -> a.branch).filter(Objects::nonNull).distinct().count();
    }

    // AVG(last_fee): NULL fees are ignored; divide by count of non-NULL fees
    BigDecimal averageFee() {
        List<BigDecimal> fees = repo.findAll().stream()
            .map(a -> a.lastFee).filter(Objects::nonNull).toList();
        if (fees.isEmpty()) return BigDecimal.ZERO;
        BigDecimal sum = fees.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
        return sum.divide(BigDecimal.valueOf(fees.size()), 2, RoundingMode.HALF_UP);
    }

    // SUM(last_fee): NULLs ignored
    BigDecimal sumFee() {
        return repo.findAll().stream()
            .map(a -> a.lastFee).filter(Objects::nonNull)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
